const bell=document.createElement('button');bell.className='pill';bell.id='notifications';bell.textContent='Inbox';$('header').append(bell);bell.onclick=()=>act(async()=>{if(!needed())return;const rows=await api('/notifications');modal('Your notifications',rows.map(n=>`<p class="notice">${esc(n.body.text)}${n.body.lessonId?`<button data-open-lesson="${esc(n.body.lessonId)}">Open lesson ↗</button>`:''}</p>`).join('')||'<p>No notifications yet.</p>');await api('/notifications',{});$$('[data-open-lesson]').forEach(b=>b.onclick=()=>{$('#dialog').close();location.hash=b.dataset.openLesson;render('feed');});});
