async function reviewTools(){const [reports,orders]=await Promise.all([api('/moderation'),api('/orders')]);modal('Reviewer workspace',`<h3>Content reports</h3>${reports.map(r=>`<div class="panel"><strong>${esc(r.title)}</strong><p>${esc(r.body)}</p><button class="secondary" data-remove="${esc(r.lesson_id)}">Remove lesson</button><button class="secondary" data-resolve="${esc(r.id)}">Resolve report</button></div>`).join('')||'<p>No open reports.</p>'}<h3>Pending payment references</h3><p class="notice">Confirm only after independently verifying money received. The app does not process payments.</p>${orders.orders.filter(o=>o.status==='pending_manual_verification').map(o=>`<div class="panel"><p>${esc(o.name)} · ${esc(o.reference)}</p><label>Access days<input id="days-${esc(o.id)}" type="number" min="1" max="365" value="30"></label><button class="secondary" data-confirm="${esc(o.id)}">Verified money received · grant access</button><button class="secondary" data-reject="${esc(o.id)}">Reject reference</button></div>`).join('')||'<p>No pending references.</p>'}`);
$$('[data-remove]').forEach(b=>b.onclick=()=>act(async()=>{await api(`/lessons/${b.dataset.remove}/remove`,{});toast('Lesson removed from the feed');reviewTools();}));$$('[data-resolve]').forEach(b=>b.onclick=()=>act(async()=>{await api('/moderation',{id:b.dataset.resolve,status:'resolved'});reviewTools();}));for(const a of ['confirm','reject'])$$(`[data-${a}]`).forEach(b=>b.onclick=()=>act(async()=>{const id=b.dataset[a];await api('/orders/review',{id,status:a==='confirm'?'confirmed':'rejected',days:Number(document.getElementById('days-'+id).value)});reviewTools();}));}
