function mediaArt(l){return lowData?'<button class="secondary media-load" data-action="loadmedia">Tap to load '+esc(l.assetType||'image')+'<small>Data saver is on</small></button>':loadedMediaArt(l);}
function saveFile(content,name,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function trackStudy(el){clearTimeout(recallTimer);recallTimer=setTimeout(()=>{if(view!=='feed'&&view!=='saved'||activePost!==el||document.hidden)return;const l=feed.find(l=>l.id===el.dataset.id);if(!l)return;try{localStorage.setItem('sm-resume:'+(me?.id||'visitor'),JSON.stringify({id:l.id,title:l.title,step:el.step||0}));}catch{}if(!seenThisSession.has(l.id)){seenThisSession.add(l.id);sessionLessons.set(l.id,{id:l.id,title:l.title,objective:l.objective});postsSinceCheck++;if(postsSinceCheck>=5&&!$('#dialog').open){postsSinceCheck=0;modal('Pause. What stayed with you?',`<p>Explain one idea from <strong>${esc(l.title)}</strong> in your own words.</p><label>Private reflection<textarea id="recall-reflection" placeholder="How does it connect to something you already know?"></textarea></label><p class="notice">This reflection stays in this dialog and is not uploaded.</p><div class="button-row"><button id="recall-check" class="primary">Try the lesson question</button><button id="recall-continue" class="secondary">Keep learning</button></div>`);$('#recall-continue').onclick=()=>$('#dialog').close();$('#recall-check').onclick=()=>{$('#dialog').close();act(()=>post(el,'quiz'));};}}},4000);}
const notesNav=document.createElement('button');notesNav.className='nav';notesNav.dataset.view='notes';notesNav.innerHTML='<span>▤</span> My course notes';$('.sidebar nav').append(notesNav);notesNav.onclick=()=>render('notes');
const tools=document.createElement('button');tools.className='pill';tools.textContent='Study tools';$('header').append(tools);tools.onclick=()=>{let resume=null;try{resume=JSON.parse(localStorage.getItem('sm-resume:'+(me?.id||'visitor'))||'null')}catch{}modal('Made for your phone',`<label class="toggle-row"><input id="data-saving" type="checkbox" ${lowData?'checked':''}> Data saver: load media only when tapped</label><label class="toggle-row"><input id="reading-mode" type="checkbox" ${document.body.classList.contains('comfortable-reading')?'checked':''}> Larger reading text</label><p class="notice">Text and device voice come first. Downloads contain text, explanations, sources and a practice question; video is not included.</p><div class="button-row"><button id="my-notes" class="primary">My course notes</button><button id="course-goals" class="secondary">My subjects & goal</button><button id="teach-from-this" class="secondary">Teach me from this</button><button id="finish-study" class="secondary">Finish & recap</button><button id="paid-tutoring" class="secondary">Live tutoring</button>${resume?`<button id="resume" class="secondary">Continue: ${esc(resume.title)}</button>`:''}</div>`);$('#data-saving').onchange=e=>{lowData=e.target.checked;try{localStorage.setItem('sm-low-data',String(lowData))}catch{}if(view==='feed'||view==='saved')act(showFeed);};$('#reading-mode').onchange=e=>{document.body.classList.toggle('comfortable-reading',e.target.checked);try{localStorage.setItem('sm-reading',String(e.target.checked))}catch{}};$('#paid-tutoring').onclick=()=>{$('#dialog').close();render('tutors');};$('#course-goals').onclick=()=>act(courseGoals);$('#teach-from-this').onclick=teachFromThis;$('#finish-study').onclick=()=>act(finishStudy);$('#my-notes').onclick=()=>{$('#dialog').close();render('notes');};if(resume)$('#resume').onclick=async()=>{$('#dialog').close();$('#subject').value='';$('#search').value='';following=false;location.hash=resume.id;await render('feed');const el=$$('.post').find(x=>x.dataset.id===resume.id),l=feed.find(x=>x.id===resume.id);if(el&&l)step(el,l,resume.step);};};
async function showNotes(){if(!me)return signupPanel('Carry your course with you.');const notes=await api('/notes');$('#content').innerHTML=`<section class="panel"><h2>Your course, in your pocket.</h2><p>Save private text notes. Turn relevant sections into lesson drafts when AI is connected, or write the explanation yourself.</p><form id="notes-form" class="form"><label>Title<input name="title" required maxlength="100" placeholder="Week 1: Introduction to management"></label><label>Subject<input name="subject" required maxlength="60" placeholder="Management"></label><label>Import a text file<input id="private-notes-file" type="file" accept=".txt,text/plain"></label><label>Or paste your notes<textarea name="body" required maxlength="120000" placeholder="Paste notes or a transcript here…"></textarea></label><button class="primary">Save private notes</button></form><p class="notice">Text files and pasted notes are supported. PDF scans, photos and recordings need extracted text or a transcript. Full notes stay private; publishing a lesson shares its selected source excerpt.</p></section><section class="panel"><h2>My saved notes</h2>${notes.map(n=>`<div class="note-row"><strong>${esc(n.title)}</strong><small>${esc(n.subject)} · ${n.characters.toLocaleString()} characters</small><div class="button-row"><button class="secondary" data-read-note="${esc(n.id)}">Read</button><button class="secondary" data-use-note="${esc(n.id)}">Create a lesson</button><button class="secondary" data-download-note="${esc(n.id)}">Download notes</button></div></div>`).join('')||'<p>Your first course notes can start here.</p>'}</section>`;$('#private-notes-file').onchange=async e=>{const f=e.target.files[0];if(f){if(f.size>480000)return toast('Use a text file smaller than 480 KB.');const t=await f.text();if(t.length>120000)return toast('Split these notes into files of up to 120,000 characters.');$('#notes-form [name=body]').value=t;if(!$('#notes-form [name=title]').value)$('#notes-form [name=title]').value=f.name.slice(0,100);}};$('#notes-form').onsubmit=e=>{e.preventDefault();act(async()=>{await api('/notes',Object.fromEntries(new FormData(e.target)));toast('Your private notes are saved.');showNotes();});};for(const action of ['read','use','download'])$$(`[data-${action}-note]`).forEach(b=>b.onclick=()=>act(async()=>{const note=await api('/notes/'+b.dataset[action+'Note']);if(action==='read')modal(note.title,'<div class="answer-text">'+esc(note.body)+'</div>');if(action==='download')saveFile(note.title+'\n'+note.subject+'\n\n'+note.body,(note.title.replace(/[^a-z0-9]+/gi,'-').slice(0,70)||'notes')+'.txt');if(action==='use')noteLesson(note);}));}
function noteLesson(note){modal('Turn notes into a lesson',`<p>${esc(note.title)} · ${esc(note.subject)}</p><form id="note-lesson" class="form"><label>Concept to explain<input name="topic" required maxlength="100" placeholder="What should this lesson teach?"></label><button class="primary" ${ai?'':'disabled'}>Create AI draft from relevant sections</button></form>${ai?'':'<p class="notice">AI is awaiting its provider key. Manual authoring is available now.</p>'}<button id="manual-note" class="secondary">Write a lesson from these notes</button>`);$('#note-lesson').onsubmit=e=>{e.preventDefault();act(async()=>{const btn=e.target.querySelector('button');btn.disabled=true;try{const r=await api('/ai',{mode:'lesson',noteId:note.id,subject:note.subject,topic:new FormData(e.target).get('topic')});$('#dialog').close();await render('create');editor(r.draft);}finally{btn.disabled=false}});};$('#manual-note').onclick=async()=>{$('#dialog').close();await render('create');editor({noteId:note.id,title:'',subject:note.subject,objective:'',slides:[{text:'',narration:''}],example:'',question:'',options:['',''],answer:0,rationale:'',source:note.body.slice(0,7000)});};}
