async function courseGoals(){if(!needed())return;const c=await api('/course'),subjectsList=await api('/subjects');modal('Make this your course feed',`<form id="course-form" class="form"><fieldset><legend>Subjects you are studying</legend>${subjectsList.map(x=>`<label class="toggle-row"><input type="checkbox" name="subjects" value="${esc(x)}" ${c?.subjects.includes(x)?'checked':''}>${esc(x)}</label>`).join('')}</fieldset><label>Other subjects (comma separated)<input name="extra" maxlength="400" value="${esc(c?.subjects.filter(x=>!subjectsList.includes(x)).join(', ')||'')}" placeholder="Chemistry, geography"></label><label>Your learning goal<textarea name="goal" maxlength="500" required placeholder="Understand my first-year management course">${esc(c?.goal||'')}</textarea></label><label>Daily study minutes<input name="daily" type="number" min="5" max="120" value="${c?.daily||20}" required></label><button class="primary">Save my course feed</button></form><p class="notice">Recommendations use your subjects, recent practice and your feedback. Your goal is a planning note; it does not imply verified curriculum coverage.</p>`);$('#course-form').onsubmit=e=>{e.preventDefault();act(async()=>{const f=new FormData(e.target),subjects=[...f.getAll('subjects'),...String(f.get('extra')).split(',').map(s=>s.trim()).filter(Boolean)];await api('/course',{subjects,goal:f.get('goal'),daily:Number(f.get('daily'))});$('#dialog').close();$('#subject').value='';following=false;toast('Your subjects and goal are saved.');render('feed');});};}
function teachFromThis(){if(!needed())return;modal('Teach me from this',`<p>Bring a real-life example, clip transcript or image description. Turn a supported connection into a lesson.</p><form id="teach-from-form" class="form"><label>Subject<input name="subject" required maxlength="60" placeholder="Physics"></label><label>Idea to understand<input name="topic" required maxlength="100" placeholder="Forces in a football kick"></label><label>Content description or transcript<textarea name="source" required maxlength="18000" placeholder="Describe what is shown or paste the transcript. AI will use only this supplied text."></textarea></label><label>Original source link (optional)<input name="url" type="url" maxlength="1500" placeholder="https://…"></label><button class="primary" ${ai?'':'disabled'}>Create a reviewed AI lesson draft</button><button id="teach-manually" type="button" class="secondary">Explain it myself</button></form><p class="notice">Links identify your source; the app does not fetch clips or interpret images automatically. Supply the transcript or description and use content you have permission to share. Every draft requires review.</p>${ai?'':'<p class="notice">AI is awaiting a provider key. You can write the lesson yourself now.</p>'}`);const values=()=>Object.fromEntries(new FormData($('#teach-from-form')));$('#teach-from-form').onsubmit=e=>{e.preventDefault();act(async()=>{const b=e.target.querySelector('button');b.disabled=true;try{const f=values(),source=f.source+(f.url?'\n\nSource supplied by author: '+f.url:'');const r=await api('/ai',{mode:'lesson',subject:f.subject,topic:f.topic,source});$('#dialog').close();await render('create');editor(r.draft);}finally{b.disabled=false}});};$('#teach-manually').onclick=async()=>{const f=values();if(!f.source.trim()||!f.subject.trim()||!f.topic.trim())return toast('Add the subject, idea and description first.');$('#dialog').close();await render('create');editor({title:f.topic,subject:f.subject,objective:'',slides:[{text:'What this example teaches',narration:''}],example:'',question:'',options:['',''],answer:0,rationale:'',source:f.source+(f.url?'\nSource supplied by author: '+f.url:'')});};}
async function lessonJourney(l,el){const j=await api(`/lessons/${l.id}/journey`);modal('Go deeper: '+l.title,`<div class="journey-step"><small>1 · WORKED EXAMPLE</small><p class="answer-text">${esc(j.example)}</p></div><div class="journey-step"><small>2 · APPLY THE IDEA</small><p>${esc(j.question)}</p><button id="journey-practice" class="primary">Try the practice question</button></div><div class="journey-step"><small>3 · CONNECT ANOTHER IDEA</small>${j.related.map(r=>`<button class="connection" data-connected="${esc(r.id)}"><strong>${esc(r.title)}</strong><small>${esc(r.connection)} · ${esc(r.subject)}</small></button>`).join('')||'<p>No related lessons are published yet. Add your own explanation below.</p>'}</div><div class="button-row"><button id="journey-explain" class="secondary">Add my explanation</button><button id="helpful-yes" class="secondary">This was useful</button><button id="helpful-no" class="secondary">Needs improvement</button></div><p class="notice">Related posts share a subject or an explicit student-explanation link. This is not a verified prerequisite map.</p>`);$('#journey-practice').onclick=()=>{$('#dialog').close();act(()=>post(el,'quiz'));};$('#journey-explain').onclick=()=>{$('#dialog').close();act(()=>post(el,'explain'));};$$('[data-connected]').forEach(b=>b.onclick=async()=>{$('#dialog').close();$('#subject').value='';$('#search').value='';following=false;location.hash=b.dataset.connected;await render('feed');});for(const yes of [true,false])$(yes?'#helpful-yes':'#helpful-no').onclick=()=>act(async()=>{await api(`/lessons/${l.id}/helpful`,{helpful:yes});toast('Feedback saved for your next feed.');});}
async function finishStudy(){if(!needed())return;const recap=await api('/recap?since='+sessionStarted),seen=[...sessionLessons.values()],c=await api('/course');modal('A good place to pause',`<p>You spent time with ${seen.length} different lessons in this session.</p><ul>${seen.map(l=>'<li>'+esc(l.title)+'<small class="recap-objective">'+esc(l.objective)+'</small></li>').join('')||'<li>Start with one short lesson, then explain it in your own words.</li>'}</ul><p>${recap.checks.correct} correct answers from ${recap.checks.attempts} practice attempts.</p>${c?'<p class="notice">Your goal: '+esc(c.goal)+'<br>Daily target: '+c.daily+' minutes.</p>':''}<h3>One next step</h3><p>Close your notes and explain one idea. Return to a question you missed when you study again.</p><div class="button-row"><button id="download-recap" class="secondary">Keep my recap</button><button id="end-session" class="primary">Finish for now</button><button id="continue-session" class="secondary">Continue learning</button></div><p class="notice">Visible lessons and practice results are activity evidence, not proof of mastery.</p>`);$('#download-recap').onclick=()=>saveFile('Study Media session\n\n'+seen.map(l=>l.title+' — '+l.objective).join('\n')+'\n\n'+recap.checks.correct+' correct / '+recap.checks.attempts+' practice attempts.\nNext: explain one idea without notes.','study-media-recap.txt');$('#continue-session').onclick=()=>$('#dialog').close();$('#end-session').onclick=()=>{$('#dialog').close();leave();stop();clearTimeout(recallTimer);observer?.disconnect();activePost=null;autoVoice=false;voice.textContent='Voice off';view='finished';document.body.classList.remove('feed-mode');$('#content').innerHTML='<section class="panel session-finish"><h2>A little wiser. A good place to stop.</h2><p>Take a break. Your notes and study plan will be here when you return.</p><button id="restart-study" class="primary">Start another study session</button></section>';$('#restart-study').onclick=()=>{seenThisSession.clear();sessionLessons.clear();postsSinceCheck=0;sessionStarted=Date.now();render('feed');};};}
let tutorClock=null;
const tutorNav=document.createElement('button');tutorNav.className='nav';tutorNav.dataset.view='tutors';tutorNav.innerHTML='<span>◉</span> Live tutoring';$('.sidebar nav').append(tutorNav);tutorNav.onclick=()=>render('tutors');
const currencyDigits=c=>new Intl.NumberFormat('en',{style:'currency',currency:c}).resolvedOptions().maximumFractionDigits;const money=(minor,currency)=>currency+' '+(minor/10**currencyDigits(currency)).toFixed(currencyDigits(currency));
async function showTutoring(){if(!me)return signupPanel('Learn with a tutor.');const [listing,sessions,bookings,earnings]=await Promise.all([api('/tutoring/offers'),api('/tutoring/sessions'),api('/tutoring/bookings'),api('/tutoring/earnings')]);$('#content').innerHTML=`<section class="panel"><span class="badge">PAID LIVE TUTORING</span><h2>A real teacher or an AI tutor.</h2><p>See the price, time and cancellation terms before booking. Only verified payment unlocks a classroom.</p><div class="button-row"><button id="offer-create" class="primary">Offer tutoring</button><button id="slot-create" class="secondary">Schedule my session</button></div>${listing.paymentReady?'':'<p class="notice">Payments await receiving instructions. Booking is disabled until these are configured.</p>'}</section><section class="panel"><h2>Upcoming sessions</h2>${sessions.map(s=>`<div class="note-row"><span class="badge">${s.kind==='ai'?'AI AVATAR':'HUMAN TEACHER'}</span><h3>${esc(s.title)}</h3><p>${esc(s.tutor)} · ${esc(s.subject)}<br>${new Date(s.start).toLocaleString()} · ${s.minutes} minutes · up to ${s.capacity} students</p><strong>${money(s.price,s.currency)} per student</strong><p class="notice">${esc(s.terms)}</p>${s.owner===me.id?`<button class="secondary" data-teacher-enter="${esc(s.id)}">Open my classroom</button><button class="secondary" data-cancel-class="${esc(s.id)}">Cancel session</button>`:`<button class="primary" data-book="${esc(s.id)}" ${listing.paymentReady&&(s.kind!=='ai'||listing.aiReady)?'':'disabled'}>Reserve & pay</button>`}${me.admin?`<button class="secondary" data-complete-class="${esc(s.id)}">Verify completed after end</button>`:''}</div>`).join('')||'<p>No sessions have been scheduled. Tutors can create listings and submit them for review.</p>'}</section><section class="panel"><h2>My bookings</h2>${bookings.map(k=>`<div class="note-row"><strong>${esc(k.title)}</strong><p>${new Date(k.start).toLocaleString()} · ${money(k.price,k.currency)} · ${esc(k.status)}</p>${me.admin?`<small>${esc(k.student_name)} · Payment reference: ${esc(k.reference||'none')}</small>`:''}<div class="button-row">${k.student===me.id&&k.status==='reserved'?`<button class="secondary" data-payment="${esc(k.id)}">Submit payment reference</button>`:''}${k.student===me.id&&k.status==='confirmed'?`<button class="primary" data-enter-tutor="${esc(k.session_id)}">Enter classroom</button>`:''}${k.student===me.id&&['reserved','payment_pending','confirmed'].includes(k.status)?`<button class="secondary" data-cancel-booking="${esc(k.id)}">Cancel / request refund</button>`:''}${me.admin&&k.status==='payment_pending'?`<button class="secondary" data-verify="${esc(k.id)}">Verify money received</button>`:''}${me.admin&&k.status==='refund_requested'?`<button class="secondary" data-refund="${esc(k.id)}">Record refund actually sent</button>`:''}</div></div>`).join('')||'<p>No bookings yet.</p>'}</section><section class="panel"><h2>${me.admin?'Listing review':'My tutoring listings'}</h2>${listing.offers.filter(o=>me.admin||o.owner===me.id).map(o=>`<div class="note-row"><strong>${esc(o.title)}</strong><p>${esc(o.tutor)} · ${o.kind==='ai'?'AI':'Human'} · ${money(o.price,o.currency)} · ${esc(o.status)}</p>${me.admin&&o.status==='pending'?`<button class="secondary" data-approve-tutor="${esc(o.id)}">Review & approve</button>`:''}</div>`).join('')||'<p>You have not submitted a listing.</p>'}</section><section class="panel"><h2>Earnings & payouts</h2><p>These are reviewed session earnings. A payout is recorded only after money is sent outside the app.</p>${earnings.map(e=>`<div class="note-row"><strong>${money(e.net,e.currency)}</strong><p>Gross ${money(e.gross,e.currency)} · Platform fee ${money(e.fee,e.currency)} · ${esc(e.status)}</p>${me.admin&&e.status==='payable'?`<button class="secondary" data-payout="${esc(e.booking_id)}">Record payout actually sent</button>`:''}</div>`).join('')||'<p>No completed-session earnings yet.</p>'}</section>`;
$('#offer-create').onclick=()=>tutorOffer();$('#slot-create').onclick=()=>tutorSlot(listing.offers.filter(o=>o.status==='approved'&&(o.owner===me.id||me.admin)));
$$('[data-book]').forEach(btn=>btn.onclick=()=>act(async()=>{const k=await api('/tutoring/bookings',{sessionId:btn.dataset.book});modal('Reservation: verify before class',`<p>Pay ${money(k.amount,k.currency)} using the operator’s instructions below.</p><p class="answer-text">${esc(k.instructions)}</p><p class="notice">${esc(k.terms)}<br>Your reservation lasts up to 15 minutes. A reference alone does not confirm payment.</p><form id="reservation-payment" class="form"><label>Payment reference<input name="reference" required maxlength="200"></label><button class="primary">Submit for verification</button></form>`);$('#reservation-payment').onsubmit=e=>{e.preventDefault();act(async()=>{await api(`/tutoring/bookings/${k.id}/payment`,{reference:new FormData(e.target).get('reference')});$('#dialog').close();showTutoring();});};}));
for(const name of ['teacher-enter','enter-tutor'])$$(`[data-${name}]`).forEach(b=>b.onclick=()=>act(()=>enterTutor(b.dataset[name==='teacher-enter'?'teacherEnter':'enterTutor'])));
$$('[data-cancel-class]').forEach(b=>b.onclick=()=>act(async()=>{await api(`/tutoring/sessions/${b.dataset.cancelClass}/cancel`,{});toast('Class cancelled. Paid bookings now require refund review.');showTutoring();}));
$$('[data-complete-class]').forEach(b=>b.onclick=()=>act(async()=>{await api(`/tutoring/sessions/${b.dataset.completeClass}/complete`,{delivered:true});toast('Completed-session earnings recorded.');showTutoring();}));
$$('[data-cancel-booking]').forEach(b=>b.onclick=()=>act(async()=>{const k=await api(`/tutoring/bookings/${b.dataset.cancelBooking}/cancel`,{});toast(k.notice);showTutoring();}));
$$('[data-approve-tutor]').forEach(b=>b.onclick=()=>{const o=listing.offers.find(x=>x.id===b.dataset.approveTutor);modal('Review tutor listing',`<p>${esc(o.title)} · ${esc(o.tutor)} · ${money(o.price,o.currency)}</p><p class="answer-text">${esc(o.description)}</p><p class="notice">${esc(o.terms)}</p><form id="tutor-approval" class="form"><label>Platform fee (%)<input name="fee" type="number" min="0" max="50" step="0.01" value="0" required></label><label class="toggle-row"><input name="reviewed" type="checkbox" required>I checked tutor suitability, pricing and terms</label><button class="primary">Approve listing</button></form>`);$('#tutor-approval').onsubmit=e=>{e.preventDefault();act(async()=>{await api('/tutoring/approve',{id:o.id,fee:Math.round(Number(new FormData(e.target).get('fee'))*100)});$('#dialog').close();showTutoring();});};});
for(const kind of ['payment','verify','refund','payout'])$$(`[data-${kind}]`).forEach(b=>b.onclick=()=>{const bid=b.dataset[kind],k=bookings.find(x=>x.id===bid);modal(kind==='verify'?'Verify actual payment':'Record '+kind,`<p>${k?money(k.price,k.currency)+' · '+esc(k.title):'Record this transfer only after it has been sent.'}</p><form id="tutor-money" class="form">${kind==='verify'?'<label class="toggle-row"><input type="checkbox" required>I independently verified the full amount received</label>':'<label>Transfer reference<input name="reference" required maxlength="200"></label>'}<button class="primary">${kind==='verify'?'Confirm payment':kind==='payment'?'Submit reference':'Record transfer actually sent'}</button></form>`);$('#tutor-money').onsubmit=e=>{e.preventDefault();act(async()=>{const reference=new FormData(e.target).get('reference');if(kind==='payout')await api('/tutoring/payout',{bookingId:bid,reference,sent:true});else await api(`/tutoring/bookings/${bid}/${kind}`,{reference,received:true,paid:true});$('#dialog').close();showTutoring();});};});}
function tutorOffer(){modal('Submit a tutoring offer',`<form id="tutor-offer" class="form"><label>Tutor type<select name="kind"><option value="teacher">Real teacher</option>${me.admin?'<option value="ai">AI avatar tutor</option>':''}</select></label><label>Title<input name="title" required maxlength="100"></label><label>Subject<input name="subject" required maxlength="60"></label><label>What you teach and your relevant experience<textarea name="description" required maxlength="1500"></textarea></label><label>Price per student<input name="price" type="number" min="0.01" step="0.01" required></label><label>Currency<select name="currency"><option>USD</option><option>SSP</option><option>UGX</option><option>KES</option></select></label><label>AI question limit (used for AI sessions)<input name="maxTurns" type="number" min="5" max="60" value="20" required></label><label>Cancellation and refund terms<textarea name="terms" required maxlength="1500" placeholder="State deadlines and how refund requests will be reviewed."></textarea></label><button class="primary">Submit for review</button></form>`);$('#tutor-offer [name=currency]').onchange=e=>{const factor=10**currencyDigits(e.target.value);const price=$('#tutor-offer [name=price]');price.step=String(1/factor);price.min=String(1/factor);};$('#tutor-offer').onsubmit=e=>{e.preventDefault();act(async()=>{const f=Object.fromEntries(new FormData(e.target));await api('/tutoring/offers',{...f,price:Math.round(Number(f.price)*10**currencyDigits(f.currency)),maxTurns:Number(f.maxTurns)});$('#dialog').close();showTutoring();});};}
function tutorSlot(offers){if(!offers.length)return toast('Submit a tutor listing and have it approved first.');modal('Schedule a tutoring session',`<form id="tutor-slot" class="form"><label>Approved listing<select name="offerId">${offers.map(o=>`<option value="${esc(o.id)}">${esc(o.title)}</option>`).join('')}</select></label><label>Start time (your device timezone)<input name="start" type="datetime-local" required></label><label>Session minutes<input name="minutes" type="number" min="5" max="120" value="30" required></label><p class="notice">Human classrooms allow up to 7 students plus the teacher.</p><label>Student seats<input name="capacity" type="number" min="1" max="7" value="1" required></label><button class="primary">Schedule</button></form>`);$('#tutor-slot').onsubmit=e=>{e.preventDefault();act(async()=>{const f=Object.fromEntries(new FormData(e.target));await api('/tutoring/sessions',{offerId:f.offerId,start:new Date(f.start).getTime(),minutes:Number(f.minutes),capacity:Number(f.capacity)});$('#dialog').close();showTutoring();});};}
async function enterTutor(sid){const c=await api(`/tutoring/sessions/${sid}/classroom`);if(c.kind==='teacher'){await join({id:c.room_id,title:c.title,host:(await api('/tutoring/sessions')).find(s=>s.id===sid)?.owner});return;}leave();stop();clearInterval(tutorClock);document.body.classList.remove('feed-mode');const notes=await api('/notes');$('#content').innerHTML=`<section class="panel ai-classroom"><span class="badge">AI TUTOR · SOFTWARE, NOT A HUMAN</span><h2>${esc(c.title)}</h2><div id="tutor-avatar" class="tutor-avatar" aria-hidden="true"><div class="avatar-face"><i></i><i></i><b></b></div></div><p id="tutor-time"></p><p id="tutor-budget">${c.remaining} questions remaining</p><div id="tutor-transcript" class="room-chat"></div><form id="ai-tutor-form" class="form"><label>Use my private notes<select name="noteId"><option value="">Use the text below</option>${notes.map(n=>`<option value="${esc(n.id)}">${esc(n.title)}</option>`).join('')}</select></label><label>Study material or context<textarea name="context" maxlength="8000"></textarea></label><label>Your question<input name="question" required maxlength="1500"></label><button class="primary">Ask my AI tutor</button></form><div class="button-row"><button id="stop-tutor-voice" class="secondary">Stop voice</button><button id="leave-ai-tutor" class="secondary">Leave classroom</button></div><p class="notice">The animated avatar speaks with your device voice. Answers are AI-generated and should be checked against your course material. This is text chat with voice playback, not continuous speech recognition.</p></section>`;const add=(role,body)=>{const el=document.createElement('div');el.className='message';el.textContent=(role==='ai'?'AI tutor: ':'You: ')+body;$('#tutor-transcript').append(el);$('#tutor-transcript').scrollTop=$('#tutor-transcript').scrollHeight;};c.messages.forEach(m=>add(m.role,m.body));const tick=()=>{const seconds=Math.max(0,Math.floor((c.end-Date.now())/1000));$('#tutor-time').textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0')+' remaining';if(!seconds){clearInterval(tutorClock);$('#ai-tutor-form button').disabled=true;stop();$('#tutor-avatar').classList.remove('talking');}};tick();tutorClock=setInterval(tick,1000);$('#ai-tutor-form').onsubmit=e=>{e.preventDefault();act(async()=>{const f=Object.fromEntries(new FormData(e.target)),btn=e.target.querySelector('button');btn.disabled=true;try{const r=await api(`/tutoring/sessions/${sid}/ask`,f);add('student',f.question);add('ai',r.text);$('#tutor-budget').textContent=r.remaining+' questions remaining';if('speechSynthesis'in window){stop();const utter=new SpeechSynthesisUtterance(r.text);utter.rate=.94;$('#tutor-avatar').classList.add('talking');utter.onend=utter.onerror=()=>$('#tutor-avatar')?.classList.remove('talking');speechSynthesis.speak(utter);}e.target.querySelector('[name=question]').value='';btn.disabled=r.remaining===0||Date.now()>=c.end;}catch(err){btn.disabled=Date.now()>=c.end;throw err}});};$('#stop-tutor-voice').onclick=()=>{stop();$('#tutor-avatar').classList.remove('talking');};$('#leave-ai-tutor').onclick=()=>render('tutors');}
window.addEventListener('pagehide',()=>{leave();stop();});document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();clearTimeout(recallTimer);}});await act(async()=>{await refresh();await subjects();await render();await teasers();});

